from identity_client import get_firebase_client
from identity_models import UserLoginRequest, UserLoginResponse
import requests
import os

def email_password_login(request: UserLoginRequest):
    api_key = os.environ.get("FIREBASE_API_KEY")
    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key={api_key}"
    payload = {
        "email": request.email,
        "password": request.password,
        "returnSecureToken": True
    }
    response = requests.post(rest_api_url, json=payload).json()
    if "error" in response:
        raise Exception(response["error"]["message"])
    return UserLoginResponse(
        id_token=response["idToken"],
        refresh_token=response["refreshToken"],
        uid=response["localId"]
    )

import requests
import os

def refresh_session(refresh_token: str):
    api_key = os.environ.get("FIREBASE_API_KEY")
    rest_api_url = f"https://securetoken.googleapis.com/v1/token?key={api_key}"
    payload = {
        "grant_type": "refresh_token",
        "refresh_token": refresh_token
    }
    response = requests.post(rest_api_url, json=payload).json()
    if "error" in response:
        raise Exception(response["error"]["message"])
    return {"id_token": response["id_token"], "refresh_token": response["refresh_token"]}

from identity_client import get_firebase_client
from identity_models import PasswordResetRequest
import requests
import os

def password_reset(request: PasswordResetRequest):
    api_key = os.environ.get("FIREBASE_API_KEY")
    rest_api_url = f"https://identitytoolkit.googleapis.com/v1/accounts:sendOobCode?key={api_key}"
    payload = {
        "requestType": "PASSWORD_RESET",
        "email": request.email
    }
    response = requests.post(rest_api_url, json=payload).json()
    if "error" in response:
        raise Exception(response["error"]["message"])
    return {"message": f"Password reset email sent to {request.email}"}
